VALUES('a115036d-d999-4168-a311-18eece359c52'::uuid, 'I211010206902', '411736b8-bc1a-491f-a6ce-e34e9454ae90'::uuid, '2019-10-28 00:00:00.000', '{"sdm": {"isar": true, "datesubmitted": "2021-11-01T14:48:43.307Z", "ismaltreatment": false, "ischildfatality": false, "isfinalscreenin": false, "isrecsc_scrrenin": true, "isrecsc_screenout": false, "scnRecommendOveride": ""}, "DAType": {"DATypeDetail": [{"caseID": "", "reason": "", "Summary": "", "DAStatus": "Approved", "comments": "", "DaTypeKey": "d207bdd4-f281-4ec8-949c-8fd9657227f9", "supStatus": "Approved", "agencyName": "", "agencyType": "", "GroupNumber": null, "supComments": "", "DasubtypeKey": "49984266-b51b-42da-b074-8c9a8a475156", "GroupComment": null, "intakeAction": "", "issubtypekey": true, "DADisposition": "ScreenOUT", "agencyContact": "", "captureReason": "", "serviceTypeID": "", "ReasonforDelay": "", "supDisposition": "ScreenOUT", "GroupReasonType": null, "dispositioncode": "Scrnin", "ServiceRequestNumber": "I211010206902", "intakeserreqstatustypekey": "Review", "supMultipleDispositionDropdown": [], "intakeMultipleDispositionDropdown": [{"text": "Close Case", "value": "Closed"}, {"text": "Screen In", "value": "Scrnin"}, {"text": "Screen Out", "value": "ScreenOUT"}]}]}, "agency": "CW", "roacps": null, "General": {"Time": "2024-04-16T15:23:37.801Z", "Iscps": null, "Agency": "CW", "Author": "VanessaBlackwell", "Purpose": "d207bdd4-f281-4ec8-949c-8fd9657227f9~CW", "countyid": "1b7ae41e-e77a-4a1e-a0a3-cda5292cde0b", "Narrative": "<p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Reporter:&nbsp;Steve Chop. SW</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Address:&nbsp;Northwest Hospital</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Telephone:&nbsp;(410) 496-8718</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Mother:&nbsp;Demetria Taylor</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">DOB:&nbsp;01/21/1979</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Race: AA</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Telephone:&nbsp;(443) 453-1204</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Address:&nbsp;1420 Langford Rd, 21207</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Victim Child: Donnell Tasker&nbsp;DOB/Age: 4/15/04 SEX: M&nbsp;&nbsp;RACE:&nbsp;</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Donnell was brought to Northwest Hospital for aggression on 10/27/21 and had to be tazed three times by the police to control him.&nbsp;He has severe autism and cannot communicate.&nbsp;Donnell attends Maiden Choice.&nbsp;On Friday, he was ready for discharge.&nbsp;The mother had no transportation and reached out to the school who instructed her not to pick him up.&nbsp;Mother requested services and was declined because the family has many resources through Autism Waiver. However they were unable to place him due to his level of aggression. According to Mr. Chop, Mom receives 50 hours of in home services for the child, however it seems that she no longer wants him.</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Reportedly, the hospital must do an LCT first and the mother must utilize all resources available to her first. However, according to Mr. Chop, he works in the ER and it is not a treatment facility. The child is ready for discharge from the hospital and it is not his role to complete a LCT as the mother is refusing to pick up the child with the schools encouragement. </span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">VPA Specialist, Norah Stephanos was consulted on this matter. She advised that Mary Leslie (LCT) is going to see if KKI (the outpatient tx provider) will submit the LCT form). Mary will also reach out to the state to let them know that NW Hospital is not following the hospital protocol on this matter. </span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">The following resources were provided to the mother:</span></p><p>1. Maryland Coalition of Families:&nbsp;</p><p><a href=\"http://www.mdcoalition.org/get-involved/impacting-policy\" target=\"_blank\" style=\"color: rgb(17, 85, 204);\">http://www.mdcoalition.org/get-involved/impacting-policy</a></p><p><br></p><p><a href=\"http://www.mdcoalition.org/get-involved/become-a-family-leader\" target=\"_blank\" style=\"color: rgb(17, 85, 204);\">http://www.mdcoalition.org/get-involved/become-a-family-leader</a>&nbsp;</p><p><br></p><p><span style=\"color: rgb(51, 51, 51);\">Sandra Yetkin, Statewide Program Manager Family Peer Support</span></p><p><span style=\"color: rgb(102, 102, 102);\">office: 443-741-8681,&nbsp;</span><a href=\"mailto:syetkin@mdcoalition.org\" target=\"_blank\" style=\"color: rgb(113, 168, 70);\">syetkin@mdcoalition.org</a></p><p><br></p><p>2. Disability Rights Maryland - (if she feels her son is not getting access to a free and appropriate education due to his disability)</p><p>Phone:&nbsp;410-727-6352</p><p><a href=\"https://disabilityrightsmd.org/\" target=\"_blank\" style=\"color: rgb(17, 85, 204); background-color: rgb(255, 255, 255);\">https://disabilityrightsmd.org/</a></p><p>&nbsp;</p><p><br></p><p>UPDATE 11/2/21: VPA Spec. Norah Stephanos has been in communication with Mary Leslie with LCT. Ms. Leslie emailed the following update: \"<span style=\"color: rgb(31, 73, 125);\">No, I had a phone meeting with Cathy Groschan, KKI, yesterday.&nbsp;He is on their waiting list for NBU services.&nbsp;She said Mom is very limited, and thought she may be taking him home from the hospital ER at Northwest, but wasn’t sure.&nbsp;She said it is difficult to get Mom on the phone and she doesn’t know how to use a computer.&nbsp;She also said the social worker at his school, Maidenchoice, was trying to help the family.&nbsp;I haven’t received a referral from the hospital, so don’t know whether he is stuck there or not.&nbsp;KKI is not making a referral.&nbsp;</span></p><p><span style=\"color: rgb(31, 73, 125);\">&nbsp;I send KKI the VPA info packet which clearly states that the Autism Waiver should be the agency to apply to for a residential placement (if needed).&nbsp;She said the school SW has asked to speak with the Autism Waiver coordinator’s supervisor.&nbsp;If I hear anything back, I will let you know.\"</span></p><p><br></p><p>History:</p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">In CJAMS, intake #211010183999, AD Jane Gehring noted that DSS would not be taking this case. This case was closed in August of 2021.</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">UPDATE: CV</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">11/8/21- Steve Chop called and reported that Donell tasker  is still in the ER and the mother is still refusing to pick him up from the ER.  </span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Reporter:&nbsp;Steve Chop. SW</span></p><p><span style=\"color: rgb(0, 0, 0); background-color: transparent;\">Address:&nbsp;Northwest Hospital</span></p><p><span style=\"color: rgb(0, 0, 0); background-color: transparent;\">Telephone:&nbsp;(410) 496-8718</span></p>", "CreatedDate": "2021-11-01T13:46:30.145Z", "InputSource": "0bdda2ab-b74f-4d74-ba17-3b9b37a9ca19", "PurposeName": "Request for services", "RecivedDate": "11/01/2021 09:46:30 AM", "teamtypekey": "CW", "IntakeNumber": "I211010206902", "intakeservice": [{"description": "In Home Services", "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "intakesubservice": [{"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Consolidated Services", "intakeservsubtypeid": "cb3dc65e-4c48-4b65-8059-53ae4321f6bc", "intakeservsubtypekey": "COS"}], "intakeservsubtype": [{"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Request of Other Agency", "intakeservsubtypeid": "022cb37c-bd74-4dc4-8014-d6d9a2889364", "intakeservsubtypekey": "ROA"}, {"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Services to Family and Children", "intakeservsubtypeid": "03b7c2e7-09b1-4d0b-9d29-a12f53379fe2", "intakeservsubtypekey": "FPS"}, {"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Kinship Navigator", "intakeservsubtypeid": "0b932ef3-d4eb-44ea-9035-0fef6e7331ca", "intakeservsubtypekey": "SGP"}, {"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Interagency Family Preservation Services", "intakeservsubtypeid": "269ea9f0-55ad-4fa6-95e6-0c1b646cd5f0", "intakeservsubtypekey": "IFPS"}, {"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Voluntary Placement", "intakeservsubtypeid": "4e2cb2f6-004d-4bbb-95e4-d56e360d2547", "intakeservsubtypekey": "VP"}, {"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Independent Living After Care Services", "intakeservsubtypeid": "5e6358b3-e242-45aa-a16b-d28ad836ba08", "intakeservsubtypekey": "ILAC"}, {"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Consolidated Services", "intakeservsubtypeid": "cb3dc65e-4c48-4b65-8059-53ae4321f6bc", "intakeservsubtypekey": "COS"}, {"activeflag": 1, "intakeservid": "34ed3645-252d-4b1f-8b40-c3387087fed4", "typedescription": "Request to file a CINA petition", "intakeservsubtypeid": "ce037f63-18a6-4990-80bb-c8a9631d0739", "intakeservsubtypekey": "RFCP"}], "intakeservtypekey": "IHS"}], "receiveddelay": "N/A", "islocalreferal": 0, "supervisorflag": "Y",
